/bin/bash -lc "python - <<'PY'
import urllib.request,os,socket
for k in ['HTTP_PROXY','HTTPS_PROXY','ALL_PROXY','NO_PROXY']:
 print(k,os.environ.get(k,''))
for h in ['api.assemblyai.com','www.assemblyai.com']:
 try: print(h,socket.gethostbyname_ex(h))
 except Exception as e: print(type(e).__name__,str(e))
try:
 r=urllib.request.urlopen(urllib.request.Request('https://api.assemblyai.com/v2/transcript',headers={'authorization':os.environ['ASSEMBLYAI_API_KEY']}),timeout=30)
 print(r.status,r.read(1000).decode())
except Exception as e: print(type(e).__name__,str(e))
PY"

