import urllib.request,socket
urls=['https://assemblyai.com/docs/api-reference/transcripts/submit','https://raw.githubusercontent.com/AssemblyAI/assemblyai-python-sdk/master/assemblyai/types.py','https://api.assemblyai.com/openapi.json']
for i,u in enumerate(urls):
 try:
  r=urllib.request.urlopen(u,timeout=20);d=r.read();open('/tmp/aai-doc-'+str(i),'wb').write(d);print(u,r.status,len(d))
 except Exception as e: print(u,type(e).__name__,str(e))
